"""The Colab notebooks are generated by ``scripts/build_notebooks.py`` and committed.

These tests regenerate them into a temporary directory, check that every notebook is a
valid nbformat v4 document with at least six cells, that every code cell compiles, that
the shared skeleton (setup / Drive / configuration / stage run / summary) is present, and
that the committed notebooks are identical to the regenerated ones (normalised JSON:
outputs and execution counts ignored) so that they can never drift from the generator.
No notebook is executed here (they clone the repository and load models).
"""
from __future__ import annotations

import importlib.util
import json
import subprocess
import sys
from pathlib import Path

import nbformat
import pytest

REPO = Path(__file__).resolve().parent.parent
SCRIPT = REPO / "scripts" / "build_notebooks.py"
NOTEBOOK_DIR = REPO / "notebooks"
EXPECTED = [
    "00_setup_and_anchor",
    "01_baseline_and_directions",
    "02_switching_grid",
    "03_nonequilibrium",
    "04_tn_linear_response",
    "05_scale_and_checkpoints",
]


@pytest.fixture(scope="module")
def builder():
    spec = importlib.util.spec_from_file_location("build_notebooks", SCRIPT)
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


@pytest.fixture(scope="module")
def regenerated(tmp_path_factory):
    """Notebooks regenerated through the command line into a temporary directory."""
    out = tmp_path_factory.mktemp("notebooks")
    r = subprocess.run([sys.executable, str(SCRIPT), "--out", str(out)], capture_output=True, text=True,
                       cwd=str(REPO), timeout=120)
    assert r.returncode == 0, r.stdout + r.stderr
    return out


def _normalised(nb: nbformat.NotebookNode) -> dict:
    d = json.loads(nbformat.writes(nb, version=4))
    for c in d["cells"]:
        c.pop("outputs", None)
        c.pop("execution_count", None)
        c.get("metadata", {}).pop("executionInfo", None)
    return d


def test_generator_covers_all_notebooks(builder):
    assert list(builder.NOTEBOOKS) == EXPECTED
    assert set(builder.BUILDERS) == set(EXPECTED)
    assert [builder.NOTEBOOKS[s][0] for s in EXPECTED] == ["A", "B", "C", "D", "E", "F"]


@pytest.mark.parametrize("stem", EXPECTED)
def test_regenerated_notebook_is_valid(regenerated, stem):
    path = regenerated / f"{stem}.ipynb"
    assert path.exists(), f"{path} not written"
    nb = nbformat.read(path, as_version=4)
    nbformat.validate(nb)                    # raises on an invalid document
    assert nb.nbformat == 4
    assert len(nb.cells) >= 6, f"{stem}: only {len(nb.cells)} cells"
    code_cells = [c for c in nb.cells if c.cell_type == "code"]
    md_cells = [c for c in nb.cells if c.cell_type == "markdown"]
    assert len(code_cells) >= 5 and len(md_cells) >= 1
    for i, c in enumerate(code_cells):
        compile(c.source, f"{stem}:code{i}", "exec")      # every code cell must be valid Python
        assert c.outputs == [] and c.execution_count is None
    ids = [c["id"] for c in nb.cells]
    assert ids == [f"cell-{i:02d}" for i in range(len(nb.cells))]   # deterministic ids


@pytest.mark.parametrize("stem", EXPECTED)
def test_notebook_skeleton(regenerated, stem):
    """Header, repo setup, optional TNCO cell, Drive mount, configuration, stage run and summary."""
    nb = nbformat.read(regenerated / f"{stem}.ipynb", as_version=4)
    head = nb.cells[0]
    assert head.cell_type == "markdown"
    assert "Dossier-Stufe" in head.source and "Zweck" in head.source and "Ausgaben" in head.source
    src = "\n".join(c.source for c in nb.cells if c.cell_type == "code")
    assert "https://github.com/Erikiss/Language-Switching-.git" in src
    assert "claude/language-switching-non-equilibrium-ejpz0q" in src
    assert "/content/lsne-repo" in src and "requirements.txt" in src and "pip install -q -e ." in src
    assert "libboost-dev" in src and "google-research/tnco" in src and "opt_einsum" in src
    assert "google.colab" in src and "drive_root" in src and "OUT_ROOT" in src
    assert "SMOKE" in src and "FAMILIES" in src and "DTYPE" in src
    assert "traceback" in src and "summary_" in src and "json.dump" in src
    assert "python -m lsne.cli run" in src
    stage = {"00": "A", "01": "B", "02": "C", "03": "D", "04": "E", "05": "F"}[stem[:2]]
    if stage != "F":
        assert f'run_stage("{stage}"' in src
        assert "cluster_bootstrap" in src or stage in ("A", "B", "E")
    else:
        assert "shards.yaml" in src and "SHARD" in src and "manifest_ok" in src and "merge_runs" in src
    assert "MODEL" in src or stage == "F"


def test_committed_notebooks_equal_regenerated(builder, regenerated):
    """The committed notebooks must be byte-for-byte what the generator produces (normalised)."""
    drift = []
    for stem in EXPECTED:
        committed = NOTEBOOK_DIR / f"{stem}.ipynb"
        assert committed.exists(), f"{committed} is missing; run python scripts/build_notebooks.py"
        a = _normalised(nbformat.read(committed, as_version=4))
        b = _normalised(nbformat.read(regenerated / f"{stem}.ipynb", as_version=4))
        if a != b:
            drift.append(stem)
    assert not drift, f"notebooks drifted from the generator: {drift}; run python scripts/build_notebooks.py"
    assert builder.check(NOTEBOOK_DIR) == []


def test_check_mode_detects_drift(builder, tmp_path):
    """``--check`` reports a modified notebook and a missing one."""
    paths = builder.write_all(tmp_path)
    assert len(paths) == len(EXPECTED)
    assert builder.check(tmp_path) == []
    nb = nbformat.read(paths[0], as_version=4)
    nb.cells[-1].source += "\nprint('drift')\n"
    nbformat.write(nb, paths[0])
    paths[1].unlink()
    drift = builder.check(tmp_path)
    assert len(drift) == 2 and any("fehlt" in d for d in drift)
    r = subprocess.run([sys.executable, str(SCRIPT), "--check", "--out", str(tmp_path)], capture_output=True,
                       text=True, cwd=str(REPO), timeout=120)
    assert r.returncode == 1
